CREATE TYPE prescription_status AS ENUM('DRAFT','SUBMITTED','PROCESSING','READY','DISPENSED','CANCELLED');
CREATE TABLE medicine_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,description text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE medicines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid REFERENCES medicine_categories(id) ON DELETE SET NULL,code text NOT NULL UNIQUE,name text NOT NULL,generic_name text NOT NULL,unit text NOT NULL,purchase_price numeric(14,2) NOT NULL DEFAULT 0,selling_price numeric(14,2) NOT NULL DEFAULT 0,minimum_stock integer NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT medicines_prices_check CHECK(purchase_price>=0 AND selling_price>=0));CREATE INDEX medicines_name_idx ON medicines(name);CREATE INDEX medicines_generic_idx ON medicines(generic_name);
CREATE TABLE prescription_counters(counter_date date PRIMARY KEY,next_value integer NOT NULL DEFAULT 1,CONSTRAINT prescription_counter_positive_check CHECK(next_value>0));
CREATE TABLE prescriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),prescription_number text NOT NULL UNIQUE,patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT,doctor_id uuid NOT NULL REFERENCES doctors(id) ON DELETE RESTRICT,visit_id uuid NOT NULL UNIQUE REFERENCES visits(id) ON DELETE RESTRICT,status prescription_status NOT NULL DEFAULT 'DRAFT',submitted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX prescriptions_status_idx ON prescriptions(status);CREATE INDEX prescriptions_patient_idx ON prescriptions(patient_id);
CREATE TABLE prescription_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),prescription_id uuid NOT NULL REFERENCES prescriptions(id) ON DELETE CASCADE,medicine_id uuid NOT NULL REFERENCES medicines(id) ON DELETE RESTRICT,dosage text NOT NULL,frequency text NOT NULL,route text NOT NULL,duration_days integer NOT NULL,quantity integer NOT NULL,instructions text,dispensed_quantity integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT prescription_items_quantity_check CHECK(quantity>0 AND duration_days>0 AND dispensed_quantity>=0));CREATE UNIQUE INDEX prescription_items_medicine_uidx ON prescription_items(prescription_id,medicine_id);CREATE INDEX prescription_items_prescription_idx ON prescription_items(prescription_id);
